export const getGetRecentlyWatchedUrl = (params?: GetRecentlyWatchedParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/stats/recently-watched?${stringifiedParams}` : `/api/stats/recently-watched`
}

